"""Explicit synthetic engineering concepts. Never seeded into owner production sessions."""
from services.api.idea_models import CRITERIA

CASES=[
    ('The Empty Podium','A stick-figure announcer and a parrot who repeats only applause cues','An announcer mistakes the rehearsal audience for a rival broadcast and starts introducing increasingly unnecessary dignitaries. The lone parrot repeats the wrong cues until the announcer must welcome his own empty chair.','Can a proud announcer admit there is nobody left to introduce?','A row of vacant chairs gains increasingly elaborate nameplates.','The announcer finally gives the empty chair the shortest introduction and receives the only sincere applause.'),
    ('The Backwards Parade','An elderly illustrated tortoise marshal and impatient marching geese','A parade marshal faces the wrong direction and solemnly congratulates everyone leaving the square. The departing crowd mistakes the farewell for an award ceremony and forms a second parade behind him.','Who is supposed to lead when the official parade has already finished?','Every departing goose returns wearing a different improvised medal.','The marshal becomes the accidental guest of honor at his own goodbye.'),
    ('Cloud Baggage','A tiny fantasy cloud porter and a fussy giant traveler','At an airborne station, a porter carefully labels a giant cloud as fragile. The traveler keeps collecting identical clouds from the carousel while his tiny suitcase floats unnoticed above the complaints counter.','Which piece of luggage belongs to someone who cannot recognize his own weather?','A luggage carousel disappears beneath increasingly specific fragile stickers.','The traveler accepts the smallest cloud as his luggage and is delighted by how light it is.'),
    ('A Seat for the Painting','A stick-figure gallery guard and an ambitious painted portrait','A gallery guard rearranges a single waiting chair to impress a severe portrait. Visitors assume every new chair position is an important artwork and solemnly critique it while the guard tries to take a break.','Can an exhausted guard sit down without accidentally opening another exhibition?','The queue starts admiring the empty patch where the chair used to stand.','The guard gets his rest while the visitors applaud the absence of a chair.'),
    ('The Formal Picnic','Two illustrated fox siblings and a very literal mechanical butler','Two siblings hire a picnic butler that treats every crumb as a guest requiring a place card. Their hill becomes a banquet for crumbs while the siblings try increasingly polite ways to ask for a sandwich.','How can hungry siblings finish a meal that keeps inviting its own leftovers?','Tiny place cards multiply in the grass as the untouched picnic cools.','The siblings enjoy an informal snack elsewhere while the butler hosts the crumbs.')]

def concept_batch(request,rotation=0):
    ideas=[]
    for i,(title,cast,premise,conflict,escalation,ending) in enumerate(CASES,1):
        suffix='' if not rotation else f' edition {rotation}'
        ideas.append(dict(idea_id=request['batch_id']+'-'+str(i),title=title+suffix,category_group_id=request['category_group_id'],primary_genre_id=request['primary_genre_id'],secondary_genre_id=request.get('secondary_genre_id'),
            logline=premise.split('. ')[0]+'.',premise=premise,opening_visual_hook=escalation,main_characters=[cast],central_conflict=conflict,key_escalation=escalation,
            ending_direction=ending,target_emotion='Character-driven comic delight',visual_feasibility='Three to six static portrait tableaux with clear silhouettes and narration; no moving illustrations or lip synchronization.',duration_seconds=55,
            quality_audit=[dict(criterion=c,assessment='ready',evidence='Synthetic engineering fixture; this qualitative statement is not independently verified creative quality.') for c in CRITERIA]))
    from .storytelling_fixtures import no_mirror,retention_plan
    for idea in ideas:idea.update(human_mirror=no_mirror(),retention_plan=retention_plan())
    return dict(schema_version='2.0',category_group_id=request['category_group_id'],primary_genre_id=request['primary_genre_id'],ideas=ideas)
